def is_email(s: str) -> bool:
    if s.count('@') != 1:
        return False
    local, domain = s.split('@')
    if not local:
        return False
    if '.' not in domain:
        return False
    if domain.startswith('.') or domain.endswith('.'):
        return False
    return True
