/**
 * Converts a title into a URL-safe slug.
 * Handles accents, punctuation, repeated separators, and length limits.
 */
function slugify(title, { maxLength = 80 } = {}) {
  return title
    .normalize('NFKD')                 // split accented chars into base + diacritic
    .replace(/[\u0300-\u036f]/g, '')    // strip diacritics
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9\s-]/g, '')       // drop anything not alphanumeric/space/hyphen
    .replace(/[\s_-]+/g, '-')           // collapse whitespace/underscores/hyphens
    .replace(/^-+|-+$/g, '')           // trim leading/trailing hyphens
    .slice(0, maxLength)
    .replace(/-+$/g, '');              // trim hyphen left dangling by slice
}

module.exports = { slugify };
```

